const raw = $input.first().json;
const item = raw && raw.body ? raw.body : raw;
const startedAt = new Date().toISOString();

if (!item.execution_id) {
  throw new Error('Missing execution_id in payload');
}
if (!item.callback || !item.callback.url || !item.callback.secret) {
  throw new Error('Missing callback.url or callback.secret in payload');
}

const config = item.config || {};
const threshold = typeof config.lead_score_threshold === 'number' ? config.lead_score_threshold : 75;
const simulateFailure = config.simulate_failure === true;

const providedItems = item.input && Array.isArray(item.input.items) ? item.input.items : [];
const items = providedItems.length > 0 ? providedItems : [
  { subject: 'Need pricing for automation suite', body: 'Hi team, we want a quote and a demo this week. Urgent rollout.' },
  { subject: 'Interested in your platform', body: 'Considering options for next quarter, would like to evaluate a trial.' },
  { subject: 'Newsletter signup confirmation', body: 'Thanks for subscribing. Click here to unsubscribe.' }
];

const buildCallback = (status, result, error, metrics) => {
  const finishedAt = new Date().toISOString();
  return {
    callbackUrl: item.callback.url,
    callbackSecret: item.callback.secret,
    callbackBody: {
      execution_id: item.execution_id,
      agent_instance_id: item.agent_instance_id,
      template_id: item.template_id,
      status,
      n8n_execution_id: $execution.id,
      started_at: startedAt,
      finished_at: finishedAt,
      metrics,
      result,
      error
    },
    httpResponse: {
      received: true,
      execution_id: item.execution_id,
      status
    }
  };
};

if (simulateFailure) {
  return [{
    json: buildCallback(
      'failed',
      null,
      { code: 'MOCK_PROVIDER_TIMEOUT', message: 'Simulated provider timeout for demo', retryable: true },
      { input_count: items.length, output_count: 0, error_count: items.length, tokens_input: 0, tokens_output: 0, estimated_cost_usd: 0 }
    )
  }];
}

const HOT_KEYWORDS = ['pricing', 'quote', 'buy', 'purchase', 'demo', 'urgent', 'asap'];
const WARM_KEYWORDS = ['interested', 'learn more', 'evaluate', 'trial', 'roadmap', 'considering'];
const NEG_KEYWORDS = ['unsubscribe', 'newsletter', 'noreply', 'no-reply'];

const classifications = items.map((email) => {
  const text = `${email.subject || ''} ${email.body || ''}`.toLowerCase();
  let score = 10;
  const matched = [];

  for (const kw of HOT_KEYWORDS) {
    if (text.includes(kw)) { score += 25; matched.push(kw); }
  }
  for (const kw of WARM_KEYWORDS) {
    if (text.includes(kw)) { score += 15; matched.push(kw); }
  }
  for (const kw of NEG_KEYWORDS) {
    if (text.includes(kw)) { score -= 100; matched.push(kw); }
  }

  let lead_type;
  let recommended_action;
  if (score <= 0) {
    lead_type = 'not_relevant';
    recommended_action = 'Discard';
  } else if (score >= threshold) {
    lead_type = 'hot_lead';
    recommended_action = 'Create reply draft';
  } else if (score >= 50) {
    lead_type = 'warm_lead';
    recommended_action = 'Add to nurture sequence';
  } else {
    lead_type = 'cold_lead';
    recommended_action = 'Send introductory content';
  }

  const reason = matched.length > 0
    ? `Detected signals: ${matched.join(', ')}.`
    : 'No strong intent signals detected.';

  return { lead_type, score: Math.max(0, score), reason, recommended_action };
});

const counts = classifications.reduce((acc, c) => {
  acc[c.lead_type] = (acc[c.lead_type] || 0) + 1;
  return acc;
}, {});
const summary = `${classifications.length} leads classified. ${counts.hot_lead || 0} hot, ${counts.warm_lead || 0} warm, ${counts.cold_lead || 0} cold, ${counts.not_relevant || 0} not relevant.`;

return [{
  json: buildCallback(
    'success',
    {
      summary,
      data: {
        items_processed: classifications.length,
        classifications,
        summary
      }
    },
    null,
    {
      input_count: items.length,
      output_count: classifications.length,
      error_count: 0,
      tokens_input: 0,
      tokens_output: 0,
      estimated_cost_usd: 0
    }
  )
}];
